"""Independent Biology D review, standard library only.

Portable commands:
  python scripts/ib-2026-biology/continuity_change_independent.py
  python scripts/ib-2026-biology/continuity_change_independent.py --write-review

Does not import the author generator. Numerical reconstructions below are from
the question givens. Default operation verifies the existing bound review.
"""
from pathlib import Path
from collections import Counter
import math, json, hashlib, re, sys

ROOT=Path(__file__).resolve().parents[2]
DATA=ROOT/'content/ib/biology-2026-expansion/continuity-change.json'
REPORT=ROOT/'docs/ib-2026-biology/continuity-change-independent-review.json'
RECORDS=[]

def review(n,title,code,bio,visual,calculations,terms=()):
    q=BY_ID[f'ib-bio-d-{n}']
    assert title.lower() in q['title'].lower(), (n,'title changed')
    assert q['syllabusCode']==code
    assert q['level']==('sl' if n<=720 else 'ahl')
    assert q['source']['question']==q['number']==n
    assert q['source']['document']=='Independent syllabus-authored practice'
    assert q['difficulty']=='hard' and q['calculator'] is True
    assert len(q['parts'])>=2 and 6<=q['marks']<=14
    groups={g['part']:g for g in q['markScheme']}
    assert len(groups)==len(q['parts'])
    for p in q['parts']:
        st=groups[p['label']]['steps']
        assert p['marks']==sum(int(s['code'][1:]) for s in st)
        assert len({s['text'] for s in st})==len(st)
    assert sum(p['marks'] for p in q['parts'])==q['marks']
    assert len(q['diagramSvg'])<300000 and 'viewBox=' in q['diagramSvg']
    assert not re.search(r'<(?:script|style|image|foreignObject|iframe)\b|(?:href|src)\s*=',q['diagramSvg'],re.I)
    text=' '.join(s['text'] for g in q['markScheme'] for s in g['steps'])
    for token in terms:assert token.casefold() in text.casefold(),(n,'missing reasoning',token)
    calc=[]
    for label,actual,expected,unit in calculations:
        assert math.isclose(actual,expected,rel_tol=1e-8,abs_tol=1e-9),(n,label,actual,expected)
        calc.append({'quantity':label,'independentlyCalculated':actual,'expected':expected,'unit':unit,'status':'passed'})
    assert calc
    RECORDS.append({'id':q['id'],'status':'passed','canonicalQuestionSha256':hashlib.sha256(json.dumps(q,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()).hexdigest(),'scope':code+(' shared statements; no AHL machinery required.' if n<=720 else ' additional-HL mechanisms/analysis are actually required.'),'biologicalEvidence':bio,'numericalEvidence':calc,'markingEvidence':'All prompts and the complete worked scheme read; each part has a matching group and distinct awards. Numerical methods, outputs and biological explanations answer the requested command terms; assumptions and uncertainty limits retained.','visualEvidence':visual})

